/**
 * The route drawn on the hero map.
 *
 * Coordinates are in the 800 x 600 space of public/topo/hero-map.svg, whose
 * terrain is generated by scripts/generate-topo.mjs: the route starts at the
 * valley floor in the south-west corner, skirts the lake, climbs the south
 * shoulder and ends on the summit. If the terrain there changes, move these
 * points with it.
 */
export const MAP_WIDTH = 800;
export const MAP_HEIGHT = 600;

type Point = readonly [number, number];

export const ROUTE_POINTS: readonly Point[] = [
  [58, 548],
  [150, 532],
  [226, 462],
  [288, 372],
  [398, 398],
  [506, 346],
  [476, 262],
  [556, 212],
  [612, 142],
];

/** Terrain features worth a label, in the same coordinate space. */
export const SUMMIT: Point = [612, 138];
export const LAKE: Point = [322, 452];
export const WEST_PEAK: Point = [215, 150];

/** Control points of the cubic Bezier for the Catmull-Rom segment i -> i+1. */
function segment(i: number): [Point, Point, Point, Point] {
  const p = ROUTE_POINTS;
  const p0 = p[Math.max(0, i - 1)];
  const p1 = p[i];
  const p2 = p[i + 1];
  const p3 = p[Math.min(p.length - 1, i + 2)];
  return [
    p1,
    [p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6],
    [p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6],
    p2,
  ];
}

const round = (n: number) => Math.round(n * 10) / 10;

/** SVG path for the route: a smooth curve through every ROUTE_POINT. */
export const routePath: string = (() => {
  let d = `M${ROUTE_POINTS[0][0]} ${ROUTE_POINTS[0][1]}`;
  for (let i = 0; i < ROUTE_POINTS.length - 1; i++) {
    const [, c1, c2, end] = segment(i);
    d += `C${round(c1[0])} ${round(c1[1])} ${round(c2[0])} ${round(c2[1])} ${end[0]} ${end[1]}`;
  }
  return d;
})();

const STEPS_PER_SEGMENT = 24;

/** The curve flattened to points, for measuring distance along it. */
const samples: Point[] = (() => {
  const out: Point[] = [ROUTE_POINTS[0]];
  for (let i = 0; i < ROUTE_POINTS.length - 1; i++) {
    const [a, b, c, d] = segment(i);
    for (let s = 1; s <= STEPS_PER_SEGMENT; s++) {
      const t = s / STEPS_PER_SEGMENT;
      const u = 1 - t;
      out.push([
        u ** 3 * a[0] + 3 * u ** 2 * t * b[0] + 3 * u * t ** 2 * c[0] + t ** 3 * d[0],
        u ** 3 * a[1] + 3 * u ** 2 * t * b[1] + 3 * u * t ** 2 * c[1] + t ** 3 * d[1],
      ]);
    }
  }
  return out;
})();

export interface Waypoint {
  /** Position as a percentage of the map's width and height. */
  left: number;
  top: number;
  /** Distance along the route, 0 (trailhead) to 1 (summit). */
  progress: number;
}

/**
 * `count` waypoints spread evenly along the route by distance travelled, the
 * first on the trailhead and the last on the summit.
 */
export function waypointsAlongRoute(count: number): Waypoint[] {
  if (count <= 0) return [];
  const lengths = [0];
  for (let i = 1; i < samples.length; i++) {
    lengths.push(
      lengths[i - 1] +
        Math.hypot(samples[i][0] - samples[i - 1][0], samples[i][1] - samples[i - 1][1]),
    );
  }
  const total = lengths[lengths.length - 1];
  return Array.from({ length: count }, (_, n) => {
    const progress = count === 1 ? 0 : n / (count - 1);
    const target = progress * total;
    let i = lengths.findIndex((l) => l >= target);
    if (i <= 0) i = 1;
    const span = lengths[i] - lengths[i - 1] || 1;
    const t = (target - lengths[i - 1]) / span;
    const x = samples[i - 1][0] + (samples[i][0] - samples[i - 1][0]) * t;
    const y = samples[i - 1][1] + (samples[i][1] - samples[i - 1][1]) * t;
    return {
      left: round((x / MAP_WIDTH) * 100),
      top: round((y / MAP_HEIGHT) * 100),
      progress,
    };
  });
}
